package cn.kaoyan.assistant;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
public class FullBackupTest{public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("full-backup").toFile();FullBackup backup=new FullBackup(root);File original=new File(root,"attachments/a.pdf");byte[] content="包含公式和图片的原文件".getBytes("UTF-8");Files.write(original.toPath(),content);JSONObject state=new JSONObject("{\"schema\":1,\"tasks\":[],\"notes\":[],\"mistakes\":[],\"files\":[{\"id\":\"a\",\"name\":\"原件.pdf\",\"path\":\"a.pdf\",\"size\":"+content.length+"}]}");ByteArrayOutputStream out=new ByteArrayOutputStream();backup.export(out,new JSONObject(state.toString()));JSONObject preview=backup.prepare(new ByteArrayInputStream(out.toByteArray()));if(!original.exists())throw new AssertionError("prepare changed old data");JSONObject result=backup.commit(preview.getString("token"),preview.getJSONObject("state"),s->{});File restored=new File(root,"attachments/"+result.getJSONArray("files").getJSONObject(0).getString("path"));if(!Arrays.equals(content,Files.readAllBytes(restored.toPath())))throw new AssertionError("full restore bytes changed");if(!original.exists())throw new AssertionError("old original removed");int before=new File(root,"attachments").list().length;preview=backup.prepare(new ByteArrayInputStream(out.toByteArray()));boolean failed=false;try{backup.commit(preview.getString("token"),preview.getJSONObject("state"),s->{throw new IOException("disk write failed");});}catch(IOException e){failed=true;}if(!failed||new File(root,"attachments").list().length!=before)throw new AssertionError("failed commit left partial originals");preview=backup.prepare(new ByteArrayInputStream(out.toByteArray()));backup.discard(preview.getString("token"));if(!original.exists())throw new AssertionError("cancel removed source");File orphan=new File(root,"restore-11111111-1111-1111-1111-111111111111");orphan.mkdirs();Files.write(new File(orphan,"leftover").toPath(),new byte[]{1});new FullBackup(root);if(orphan.exists())throw new AssertionError("interrupted restore staging not cleaned");JSONObject shared=new JSONObject(state.toString());shared.getJSONArray("files").put(new JSONObject(shared.getJSONArray("files").getJSONObject(0).toString()).put("id","b"));ByteArrayOutputStream sharedZip=new ByteArrayOutputStream();backup.export(sharedZip,shared);JSONObject sharedPreview=backup.prepare(new ByteArrayInputStream(sharedZip.toByteArray()));JSONObject sharedResult=backup.commit(sharedPreview.getString("token"),sharedPreview.getJSONObject("state"),s2->{});String first=sharedResult.getJSONArray("files").getJSONObject(0).getString("path"),second=sharedResult.getJSONArray("files").getJSONObject(1).getString("path");if(first.equals(second)||!new File(root,"attachments/"+second).isFile())throw new AssertionError("shared source not independently restored");System.out.println("Full backup exact originals, preview isolation, restore, failure rollback and cancellation passed");}}
